import modal
import os

image = (
    modal.Image.debian_slim(python_version="3.11")
    .pip_install(
        "vllm==0.6.4.post1",
        "huggingface_hub",
        "torch",
        "numpy"
    )
    .run_commands(
        "apt-get update && apt-get install -y git"
    )
)

app = modal.App("glm47-replit")

MODEL_NAME = "zai-org/GLM-4.7-FP8"


@app.cls(image=image, gpu="B200:8", timeout=600)
class GLMModel:
    @modal.enter()
    def load_model(self):
        from vllm import LLM, SamplingParams

        self.llm = LLM(
            model=MODEL_NAME,
            tensor_parallel_size=8,
            gpu_memory_utilization=0.95,
            max_model_len=65536
        )
        self.sampling_params = SamplingParams(
            temperature=0.7,
            top_p=0.9,
            max_tokens=100000,
            repetition_penalty=1.05
        )

    @modal.method()
    def generate(self, prompt: str) -> str:
        outputs = self.llm.generate(
            [prompt],
            self.sampling_params
        )
        return outputs[0].outputs[0].text


@app.local_entrypoint()
def main():
    model = GLMModel()
    text = model.generate.call("Teszt prompt GLM-4.7-hez.")
    print(text)
