from flask import Flask, request, jsonify
import modal
import os

app = Flask(__name__)

client = modal.Client.from_env()
glm_model = client.cls_from_name("glm47-replit", "GLMModel")()


@app.route("/chat", methods=["POST"])
def chat():
    if not request.is_json:
        return jsonify({"error": "Content-Type must be application/json"}), 400

    data = request.get_json(silent=True)
    if data is None:
        return jsonify({"error": "Invalid JSON body"}), 400

    messages = data.get("messages")
    if not isinstance(messages, list) or len(messages) == 0:
        return jsonify({"error": "messages must be a non-empty list"}), 400

    last = messages[-1]
    if not isinstance(last, dict):
        return jsonify({"error": "last message must be an object"}), 400

    content = last.get("content")
    if not isinstance(content, str) or not content.strip():
        return jsonify({"error": "last message must contain non-empty content"}), 400

    prompt = content.strip()

    try:
        result = glm_model.generate.remote(prompt)
        return jsonify({"response": result})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "ok"}), 200


if __name__ == "__main__":
    port_env = os.getenv("PORT")
    try:
        port = int(port_env) if port_env is not None else 8080
    except ValueError:
        port = 8080
    app.run(host="0.0.0.0", port=port, debug=False)
```

